import{_ as t,o,c as r,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2021-09-23","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-09-23","date":"2021-09-23T00:00:00.000Z","updated":"2021-10-07T00:00:00.000Z","tags":["Ceph","分布式存储","RocksDB","BlueStore","RGW","PR审查","性能优化","Linux存储栈"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-09-23.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-09-23.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Performance_Meeting_2021-09-23.md"};function n(s,e,l,a,_,g){return o(),r("div",null,[...e[0]||(e[0]=[p("<p>本次Ceph性能会议主要讨论了以下议题：</p><ol><li><p><strong>RocksDB LRU缓存更新</strong>：由于与RocksDB新版本不兼容，Kifu修复了接口问题，并已合并到主分支。会议讨论了维护者使用最新版本RocksDB编译的问题，建议避免使用未经测试的版本。</p></li><li><p><strong>RGW OSD压缩绕过</strong>：Casey上周审查通过，已重新基于最新版本，接近合并状态。</p></li><li><p><strong>BlueStore Fighting Green Locking</strong>：Adam更新并由Sage审查，主要是小改动。会议讨论了需要进一步审查，特别是与Gabby相关的问题。</p></li><li><p><strong>BlueStore增量更新模式</strong>：正在进行测试，已更新以修复错误。</p></li><li><p><strong>TTL缓存实现</strong>：请求对管理模块的TTL缓存实现进行审查。已修复make check问题，可能需要再次审查。</p></li><li><p><strong>PG移除优化</strong>：Igor的PR有额外审查和测试，讨论了是否需要为硬盘优化。测试失败，需要进一步审查。</p></li><li><p><strong>其他更新</strong>：MDS相关的新PR需要重新基于最新版本，RGW团队的共享对象缓存PR正在等待进一步处理，MemStore清理PR目前不紧急。</p></li></ol><p>会议确定了以下行动计划：</p><ol><li><p>确认Fedora和其他前沿发行版是否使用最新版本的RocksDB，并建议避免使用未经测试的版本。</p></li><li><p>继续审查和测试RGW OSD压缩绕过、BlueStore Fighting Green Locking、BlueStore增量更新模式等PR。</p></li><li><p>确保Igor的PG移除优化PR通过测试并进行必要的审查。</p></li><li><p>下周将讨论Josh推荐的关于重构Linux存储栈的论文，建议与会者提前阅读并准备三个关键的讨论点。</p></li></ol><p>会议还提醒大家，下周会议将重点讨论Linux存储栈重构的论文，并建议与会者提前准备并分享三个关键的讨论点。</p><p>本次会议纪要涵盖了关键的讨论点、决定的事项以及后续的行动计划，对于Ceph社区的成员来说具有重要的参考价值。</p>",6)])])}const P=t(i,[["render",n]]);export{d as __pageData,P as default};
